// ─── Componentes base reusables ───────────────────────────────────────
function Card({T, children, hoverable, onClick, style={}, padding="lg"}) {
  const [hover, setHover] = React.useState(false);
  const padMap = {sm:"10px 12px", md:"14px 16px", lg:"18px 20px", xl:"24px 28px"};
  return (
    <div onClick={onClick}
      onMouseEnter={()=>hoverable&&setHover(true)}
      onMouseLeave={()=>setHover(false)}
      style={{
        background: T.card,
        border: `1px solid ${hover&&hoverable ? T.accentSolid+"66" : T.border}`,
        borderRadius: DS.r.xl,
        padding: padMap[padding]||padMap.lg,
        transition: `all 0.2s ${DS.ease}`,
        cursor: onClick?"pointer":"default",
        boxShadow: hover&&hoverable
          ? `0 8px 32px rgba(0,0,0,0.18), 0 0 0 1px ${T.accentSolid}18`
          : "0 1px 3px rgba(0,0,0,0.07)",
        transform: hover&&hoverable ? "translateY(-2px)" : "translateY(0)",
        ...style,
      }}>
      {children}
    </div>
  );
}

function Skeleton({T, width="72%", height=22, radius=6, style={}}) {
  return <div style={{width,height,borderRadius:radius,background:T?T.surface:"#1e1e2e",position:"relative",overflow:"hidden",...style}}><div style={{position:"absolute",inset:0,background:"linear-gradient(90deg,transparent 0%,rgba(255,255,255,0.07) 50%,transparent 100%)",backgroundSize:"200% 100%",animation:"skeleton 1.4s ease infinite"}}/></div>;
}

function KPI({T, label, value, sub, color, icon, accent, onClick, compact, loading}) {
  const c = color||T.accentSolid;
  return (
    <Card T={T} hoverable={!!onClick} onClick={onClick} padding={compact?"md":"lg"}
      style={{
        borderColor: accent ? c+"66" : T.border,
        boxShadow: accent ? `0 4px 24px ${c}20, 0 1px 3px rgba(0,0,0,0.07)` : "0 1px 3px rgba(0,0,0,0.07)",
      }}>
      <div style={{display:"flex",alignItems:"flex-start",gap:DS.sp.md}}>
        {icon&&<div style={{fontSize:compact?16:18,flexShrink:0,opacity:loading?0.3:0.9}}>{icon}</div>}
        <div style={{flex:1,minWidth:0}}>
          <div style={{fontSize:DS.font.xs,textTransform:"uppercase",color:T.textSm,fontWeight:DS.w.semibold,letterSpacing:0.5,marginBottom:5}}>{label}</div>
          {loading
            ? <Skeleton T={T} height={compact?18:24} width="65%" style={{marginBottom:6}}/>
            : <div style={{fontSize:compact?DS.font["2xl"]:DS.font["3xl"],fontWeight:DS.w.black,color:c,letterSpacing:-0.6,lineHeight:1}}>{value}</div>
          }
          {loading
            ? <Skeleton T={T} height={11} width="45%" style={{marginTop:6}}/>
            : sub&&<div style={{fontSize:DS.font.xs,color:T.textSm,marginTop:4}}>{sub}</div>
          }
        </div>
      </div>
    </Card>
  );
}

// Sistema de botones unificado — visualmente idéntico a BtnPrimary/BtnSecondary/BtnDanger
function Btn({T, variant="primary", size="md", icon, children, onClick, disabled, style={}, ...rest}) {
  const [hov, setHov] = React.useState(false);
  const variants = {
    primary:   {bg:"rgba(124,58,237,0.13)", color:"#a78bfa", border:"rgba(124,58,237,0.55)", shadow:"0 0 0 1px #7c3aed15, 0 4px 20px #7c3aed20", shadowHov:"0 0 0 1px #7c3aed28, 0 6px 28px #7c3aed40"},
    secondary: {bg:"transparent", color:T.textMd, border:T.border, shadow:"none", shadowHov:`0 2px 12px rgba(0,0,0,0.12)`},
    ghost:     {bg:"transparent", color:T.textMd, border:"transparent", shadow:"none", shadowHov:"none"},
    danger:    {bg:T.redBg, color:T.red, border:T.red+"55", shadow:`0 0 0 1px ${T.red}15, 0 4px 16px ${T.red}22`, shadowHov:`0 0 0 1px ${T.red}28, 0 6px 24px ${T.red}40`},
    success:   {bg:"rgba(22,163,74,0.13)", color:"#4ade80", border:"rgba(22,163,74,0.55)", shadow:"0 0 0 1px #16a34a15, 0 4px 20px #16a34a20", shadowHov:"0 0 0 1px #16a34a28, 0 6px 28px #16a34a40"},
  };
  const sizes = {
    sm: {padding:"5px 10px", fontSize:DS.font.sm, gap:5},
    md: {padding:"8px 14px", fontSize:DS.font.base, gap:6},
    lg: {padding:"10px 20px", fontSize:DS.font.lg, gap:8},
  };
  const v = variants[variant]||variants.primary;
  const s = sizes[size]||sizes.md;
  return (
    <button onClick={onClick} disabled={disabled}
      onMouseEnter={()=>!disabled&&setHov(true)}
      onMouseLeave={()=>setHov(false)}
      {...rest}
      style={{
        background: disabled?T.surface:v.bg,
        color: disabled?T.textSm:v.color,
        border: `1px solid ${v.border==="transparent"?"transparent":v.border}`,
        borderRadius: DS.r.md,
        cursor: disabled?"not-allowed":"pointer",
        fontWeight: DS.w.semibold,
        fontFamily: "'Inter',system-ui,sans-serif",
        letterSpacing:"0.01em",
        display:"inline-flex",alignItems:"center",justifyContent:"center",
        transition: `all 0.18s ${DS.ease}`,
        opacity: disabled?0.5:1,
        boxShadow: disabled?"none": hov?(v.shadowHov||v.shadow):v.shadow,
        ...s,
        ...style,
      }}>
      {icon&&<span style={{display:"inline-flex",alignItems:"center"}}>{icon}</span>}
      {children}
    </button>
  );
}

// ─── Google Drive Picker ─────────────────────────────────────────────────────
const GDRIVE_API_KEY   = import.meta.env.VITE_GOOGLE_API_KEY   || "";
const GDRIVE_CLIENT_ID = import.meta.env.VITE_GOOGLE_CLIENT_ID || "";
let _gapiReady = false, _gisReady = false;

// Pre-cargar scripts después de que el DOM esté listo — evita errores en api.js
if (GDRIVE_API_KEY && GDRIVE_CLIENT_ID) {
  window.addEventListener("load", () => {
  const s1 = document.createElement("script");
  s1.src = "https://apis.google.com/js/api.js";
  s1.async = true;
  s1.onload = () => { try { window.gapi.load("picker", () => { _gapiReady = true; }); } catch(_) {} };
  document.head.appendChild(s1);
  const s2 = document.createElement("script");
  s2.src = "https://accounts.google.com/gsi/client";
  s2.async = true;
  s2.onload = () => { _gisReady = true; };
  document.head.appendChild(s2);
  }); // fin window.addEventListener load
}

function _saveDriveToken(t, exp) {
  try { sessionStorage.setItem("_gdt", JSON.stringify({ t, exp })); } catch(_) {}
}
function _getSavedDriveToken() {
  try {
    const s = sessionStorage.getItem("_gdt");
    if (!s) return null;
    const { t, exp } = JSON.parse(s);
    return Date.now() < exp ? t : null;
  } catch(_) { return null; }
}

function _loadDriveScripts() {
  return new Promise((resolve, reject) => {
    let g = _gapiReady, s = _gisReady;
    const done = () => { if (g && s) resolve(); };
    const timer = setTimeout(() => reject(new Error("Timeout cargando scripts de Drive")), 10000);
    if (!_gapiReady) {
      const el = document.createElement("script");
      el.src = "https://apis.google.com/js/api.js";
      el.onerror = () => { clearTimeout(timer); reject(new Error("Error cargando GAPI")); };
      el.onload = () => { window.gapi.load("picker", () => { _gapiReady = g = true; clearTimeout(timer); done(); }); };
      document.head.appendChild(el);
    } else { g = true; }
    if (!_gisReady) {
      const el = document.createElement("script");
      el.src = "https://accounts.google.com/gsi/client";
      el.onerror = () => { clearTimeout(timer); reject(new Error("Error cargando GIS")); };
      el.onload = () => { _gisReady = s = true; done(); };
      document.head.appendChild(el);
    } else { s = true; }
    if (g && s) { clearTimeout(timer); resolve(); }
  });
}

// Abre el picker con un token ya disponible.
// IMPORTANTE: debe llamarse desde un click directo del usuario (no desde callback async)
function _showDrivePicker(token, onSelect, onCancel) {
  const myDrive = new window.google.picker.DocsView().setIncludeFolders(true).setSelectFolderEnabled(false);
  const shared  = new window.google.picker.DocsView(window.google.picker.ViewId.DOCS).setEnableDrives(true).setIncludeFolders(true);
  new window.google.picker.PickerBuilder()
    .setTitle("Elegir archivo de Google Drive")
    .addView(myDrive).addView(shared)
    .setOAuthToken(token)
    .setDeveloperKey(GDRIVE_API_KEY)
    .enableFeature(window.google.picker.Feature.SUPPORT_DRIVES)
    .setCallback(data => {
      if (data.action === window.google.picker.Action.PICKED && data.docs?.[0]) {
        const d = data.docs[0];
        onSelect({ name: d.name, url: d.url, id: d.id, mimeType: d.mimeType });
      } else if (data.action === window.google.picker.Action.CANCEL) {
        if (onCancel) onCancel();
      }
    })
    .build().setVisible(true);
}

// Solicita token OAuth — SINCRÓNICO para mantener el gesto del usuario.
// El popup NO se bloquea porque no hay ningún await antes de requestAccessToken.
function _requestDriveToken(onDone, onFail) {
  if (!_gisReady || !window.google?.accounts?.oauth2) {
    onFail("scripts_no_cargados");
    return;
  }
  const timeout = setTimeout(() => onFail("timeout"), 60000);
  try {
    const client = window.google.accounts.oauth2.initTokenClient({
      client_id: GDRIVE_CLIENT_ID,
      scope: "https://www.googleapis.com/auth/drive.readonly",
      callback: r => {
        clearTimeout(timeout);
        if (r.access_token) {
          const exp = Date.now() + ((r.expires_in || 3599) * 1000) - 60000;
          _saveDriveToken(r.access_token, exp);
          onDone(r.access_token);
        } else {
          onFail(r.error || "sin_token");
        }
      },
      error_callback: e => { clearTimeout(timeout); onFail(e?.type || "error"); },
    });
    client.requestAccessToken({ prompt: "consent" });
  } catch(e) { clearTimeout(timeout); onFail(e.message); }
}

// DriveBtn — botón que abre Google Drive Picker.
// Si ya tiene token guardado: 1 click → picker.
// Si no tiene token: 1 click → OAuth popup → botón muestra "✓ Elegir archivo" → 2do click → picker.
// Siempre muestra error si algo falla.
function DriveBtn({ T, onPick, size = "sm" }) {
  const [step, setStep] = React.useState("idle"); // idle | authing | authed | picking
  const tokenRef = React.useRef(_getSavedDriveToken());

  const pad = size === "sm" ? "4px 8px" : "6px 12px";
  const fs  = size === "sm" ? 11 : 12;
  const base = { ...BtnSecondary(T), padding: pad, fontSize: fs, display:"flex", alignItems:"center", gap:4, flexShrink:0, fontFamily:"'Inter',system-ui,sans-serif" };

  const driveIcon = <svg width="12" height="9" viewBox="0 0 87.3 78" style={{flexShrink:0}}>
    <path d="M6.6 66.85l3.85 6.65c.8 1.4 1.95 2.5 3.3 3.3l13.75-23.8H0c0 1.55.4 3.1 1.2 4.5z" fill="#0066da"/>
    <path d="M43.65 25L29.9 1.2C28.55 2 27.4 3.1 26.6 4.5L1.2 49.5C.4 50.9 0 52.45 0 54h27.5z" fill="#00ac47"/>
    <path d="M73.55 76.8c1.35-.8 2.5-1.9 3.3-3.3l1.6-2.75 7.65-13.25c.8-1.4 1.2-2.95 1.2-4.5H59.8l5.85 11.2z" fill="#ea4335"/>
    <path d="M43.65 25L57.4 1.2C56.05.4 54.5 0 52.85 0H34.45c-1.65 0-3.2.45-4.55 1.2z" fill="#00832d"/>
    <path d="M59.8 54H27.5L13.75 77.8c1.35.8 2.9 1.2 4.55 1.2h50.7c1.65 0 3.2-.45 4.55-1.2z" fill="#2684fc"/>
    <path d="M73.4 27.5l-12.7-22c-.8-1.4-1.95-2.5-3.3-3.3L43.65 25 59.8 54h27.45c0-1.55-.4-3.1-1.2-4.5z" fill="#ffba00"/>
  </svg>;

  const openPicker = () => {
    const tok = tokenRef.current || _getSavedDriveToken();
    if (!tok) { setStep("idle"); return; }
    if (!_gapiReady || !window.google?.picker) { setStep("idle"); return; }
    setStep("picking");
    _showDrivePicker(tok, f => { onPick(f); setStep("idle"); }, () => setStep("idle"));
  };

  if (step === "authing") return (
    <button disabled style={{...base, opacity:0.65, cursor:"wait"}}>
      <Spinner size={10} color={T.accent}/> Conectando…
    </button>
  );

  if (step === "authed") return (
    <button title="Hacé click para elegir el archivo" onClick={openPicker}
      style={{...base, background:T.green+"22", borderColor:T.green+"66", color:T.green, fontWeight:600}}>
      ✓ Elegir archivo
    </button>
  );

  if (step === "picking") return (
    <button disabled style={{...base, opacity:0.65}}>
      <Spinner size={10} color={T.accent}/> Abriendo…
    </button>
  );

  // idle — verificar si hay token guardado
  const tok = tokenRef.current || _getSavedDriveToken();
  if (tok) return (
    <button title="Elegir desde Google Drive" onClick={openPicker} style={base}>
      {driveIcon} Drive
    </button>
  );

  return (
    <button title="Conectar Google Drive" onClick={() => {
      if (!GDRIVE_API_KEY || !GDRIVE_CLIENT_ID) { alert("Drive no configurado en Vercel."); return; }
      if (!_gisReady) { alert("Cargando Drive, intentá en unos segundos..."); return; }
      setStep("authing");
      // SINCRÓNICO — sin await para mantener gesto del usuario y evitar popup bloqueado
      _requestDriveToken(
        tok => { tokenRef.current = tok; setStep("authed"); },
        err => { console.warn("[Drive]", err); setStep("idle"); }
      );
    }} style={base}>
      {driveIcon} Drive
    </button>
  );
}

